 * A set's values as a client last read them — the floor's compare-and-set (KAN-757, decision
 * `value-compare-and-set`). [matches] compares by value: [SetWeight.Measured] equality is numeric, so
 * `60` matches a stored `60.00`, and [confirmed] stands for `confirmedAt != null`.
 */
data class SetValues(
    val weight: SetWeight?,
    val effort: SetEffort?,
    val confirmed: Boolean,
) {
    fun matches(set: WorkoutSet): Boolean = weight == set.weight && effort == set.effort && confirmed == (set.confirmedAt != null)
}
