import jakarta.validation.constraints.NotNull
import java.time.Instant
import java.time.LocalDate
import java.time.LocalTime
import java.util.Optional
import java.util.UUID

data class ParticipantRequestDto(
    @field:NotNull val userId: UUID?,
    @field:NotNull val workoutId: UUID?,
)

data class CreateGroupSessionRequest(
    val name: String? = null,
    @field:NotNull(message = "Scheduled date is required")
    val scheduledDate: LocalDate?,
    val scheduledTime: String? = null,
    @field:NotNull
    @field:NotEmpty(message = "At least one participant is required")
    @field:Valid
    val participants: List<ParticipantRequestDto>?,
)

/**
 * The [PatchWorkoutRequest][com.gymie.workout.infrastructure.presentation.web.dto.PatchWorkoutRequest]
 * `Optional<String>?` shape, applied to both `name` and `scheduledTime`: the outer `?` is `null`
 * when the key is absent, `Optional.empty()`/`Optional.of(raw)` when it is present. `scheduledDate`
 * carries no such distinction -- it is absent or a date, never an explicit `null`.
 */
data class PatchGroupSessionRequest(
    val name: Optional<String>? = null,
    val scheduledDate: LocalDate? = null,
    val scheduledTime: Optional<String>? = null,
)

data class AddParticipantRequest(
    @field:NotNull val userId: UUID?,
    @field:NotNull val workoutId: UUID?,
)

/**
 * The floor's set PATCH body. [expected] is the set as the phone last read it; when present the
 * write is compare-and-set (KAN-757, decision `value-compare-and-set`). The solo route keeps
 * `PatchWorkoutSetRequest`, which refuses `expected` with `400`.
